def _cleanup_staging(keep=10):
    """PATCH 1.0.34: держим только N последних staging-папок."""
    try:
        if not STAGE_ROOT.exists():
            return
        dirs = sorted([d for d in STAGE_ROOT.iterdir() if d.is_dir()],
                      key=lambda x: x.stat().st_mtime, reverse=True)
        for old in dirs[keep:]:
            try:
                shutil.rmtree(old)
            except Exception:
                pass
    except Exception as e:
        print(f'[updater] staging cleanup failed: {e}')

def _cleanup_backups(keep=20):
    """PATCH 1.0.34: держим только N последних .bak-файлов."""
    try:
        bdir = PROJECT_DIR / 'patch_backups'
        if not bdir.exists():
            return
        baks = sorted(bdir.rglob('*.bak-*'),
                      key=lambda x: x.stat().st_mtime, reverse=True)
        for old in baks[keep:]:
            try:
                old.unlink()
            except Exception:
                pass
    except Exception as e:
        print(f'[updater] backups cleanup failed: {e}')

try:
    _cleanup_staging(10)
    _cleanup_backups(20)
except Exception as _cl_err:
    print(f'[updater] cleanup skipped: {_cl_err}')

def j_save(base: Path, j: dict) -> None:
    # PATCH 1.0.34: держим changes только у 10 самых свежих патчей — журнал не раздувается
    try:
        _sorted = sorted(j.items(), key=lambda kv: (kv[1] or {}).get('applied_at') or '', reverse=True)
        for _i, (_pid, _info) in enumerate(_sorted):
            if _i >= 10 and isinstance(_info, dict) and _info.get('changes'):
                _info['changes'] = []
    except Exception as e:
        print(f'[patcher] j_save changes trim failed: {e}')
    p = base / JOURNAL
    tmp = p.with_suffix(p.suffix + '.tmp')
    tmp.write_text(json.dumps(j, ensure_ascii=False, indent=2), encoding='utf-8')
    tmp.replace(p)
